const body = $input.first().json.body || {};
const call = body.call || {};
const analysis = call.call_analysis || {};
const custom = analysis.custom_analysis_data || {};

const q1 = Number(custom.q1_escalabilidad_score || 0);
const q2 = Number(custom.q2_diferenciacion_score || 0);
const q3 = Number(custom.q3_enfoque_score || 0);
const q4 = Number(custom.q4_compromiso_score || 0);
const total = q1 + q2 + q3 + q4;

let verdict;
if (total >= 17) verdict = 'Candidato A (Top)';
else if (total >= 13) verdict = 'Candidato B (Apto)';
else verdict = 'No Apto';

const questionsAnswered = Number(custom.questions_answered || 0);
const wantsFollowup = Boolean(custom.caller_wants_followup);

const startTs = call.start_timestamp || Date.now();
const tsUtc = new Date(startTs).toISOString();
const tsBogota = new Date(startTs).toLocaleString('es-CO', { timeZone: 'America/Bogota', hour12: false });

const candidateName = (custom.candidate_name || '').trim() || '(no proporcionado)';
const candidateCompany = (custom.candidate_company || '').trim() || '(no proporcionada)';
const summary = analysis.call_summary || '';
const sentiment = analysis.user_sentiment || '';
const recordingUrl = call.recording_url || '';
const transcriptHint = call.public_log_url || '';

const row = (label, score, obs) => `
  <tr>
    <td style="padding:6px 10px;border:1px solid #ddd;"><strong>${label}</strong></td>
    <td style="padding:6px 10px;border:1px solid #ddd;text-align:center;">${score}/5</td>
    <td style="padding:6px 10px;border:1px solid #ddd;">${obs || '<em>(sin observación)</em>'}</td>
  </tr>`;

const emailHtml = `<!DOCTYPE html>
<html lang="es"><body style="font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;max-width:680px;margin:0 auto;padding:20px;color:#222;">
  <h2 style="margin:0 0 4px 0;">Encuesta — Programa de Exportación de Servicios Modernos</h2>
  <p style="margin:0 0 16px 0;color:#666;">${tsBogota} (Bogotá) · ${call.call_id || ''}</p>

  <table style="width:100%;border-collapse:collapse;margin-bottom:16px;">
    <tr><td style="padding:6px 10px;border:1px solid #ddd;background:#f7f7f7;width:200px;"><strong>Candidato</strong></td><td style="padding:6px 10px;border:1px solid #ddd;">${candidateName}</td></tr>
    <tr><td style="padding:6px 10px;border:1px solid #ddd;background:#f7f7f7;"><strong>Empresa</strong></td><td style="padding:6px 10px;border:1px solid #ddd;">${candidateCompany}</td></tr>
    <tr><td style="padding:6px 10px;border:1px solid #ddd;background:#f7f7f7;"><strong>Preguntas respondidas</strong></td><td style="padding:6px 10px;border:1px solid #ddd;">${questionsAnswered} / 4</td></tr>
    <tr><td style="padding:6px 10px;border:1px solid #ddd;background:#f7f7f7;"><strong>Pidió seguimiento</strong></td><td style="padding:6px 10px;border:1px solid #ddd;">${wantsFollowup ? 'Sí' : 'No'}</td></tr>
  </table>

  <h3 style="margin:24px 0 8px 0;">Matriz de Evaluación</h3>
  <table style="width:100%;border-collapse:collapse;">
    <thead><tr><th style="padding:6px 10px;border:1px solid #ddd;background:#f0f0f0;text-align:left;">Pregunta</th><th style="padding:6px 10px;border:1px solid #ddd;background:#f0f0f0;width:80px;">Puntaje</th><th style="padding:6px 10px;border:1px solid #ddd;background:#f0f0f0;text-align:left;">Observación</th></tr></thead>
    <tbody>
      ${row('1. Escalabilidad', q1, custom.q1_escalabilidad_obs)}
      ${row('2. Diferenciación', q2, custom.q2_diferenciacion_obs)}
      ${row('3. Enfoque comercial', q3, custom.q3_enfoque_obs)}
      ${row('4. Compromiso', q4, custom.q4_compromiso_obs)}
      <tr><td style="padding:8px 10px;border:1px solid #ddd;background:#f7f7f7;"><strong>TOTAL</strong></td><td style="padding:8px 10px;border:1px solid #ddd;text-align:center;background:#f7f7f7;"><strong>${total}/20</strong></td><td style="padding:8px 10px;border:1px solid #ddd;background:#f7f7f7;"><strong>${verdict}</strong></td></tr>
    </tbody>
  </table>

  <h3 style="margin:24px 0 8px 0;">Resumen de la llamada</h3>
  <p style="line-height:1.5;margin:0 0 8px 0;">${summary || '<em>(sin resumen)</em>'}</p>
  <p style="margin:0 0 16px 0;"><strong>Sentimiento:</strong> ${sentiment || '(no clasificado)'}</p>

  ${recordingUrl ? `<p><a href="${recordingUrl}">▶ Escuchar la grabación</a></p>` : ''}
  ${transcriptHint ? `<p><a href="${transcriptHint}">📝 Ver transcripción y log</a></p>` : ''}
</body></html>`;

const emailSubject = `[Encuesta] ${verdict} — ${candidateName} / ${candidateCompany}`;

return [{
  json: {
    timestamp_utc: tsUtc,
    timestamp_bogota: tsBogota,
    call_id: call.call_id || '',
    candidate_name: candidateName,
    candidate_company: candidateCompany,
    q1_escalabilidad: q1,
    q2_diferenciacion: q2,
    q3_enfoque: q3,
    q4_compromiso: q4,
    total,
    verdict,
    questions_answered: questionsAnswered,
    wants_followup: wantsFollowup ? 'Sí' : 'No',
    summary,
    sentiment,
    recording_url: recordingUrl,
    email_subject: emailSubject,
    email_html: emailHtml,
  }
}];

